-- 0006 access hardening: least-privilege browser (anon/authenticated) access to every public table.
-- Policies were generated by drizzle-kit from src/db/schema.ts; the rest is hand-written:
--   [hand-edit 1] app.current_user_role(), the role counterpart of app.current_organization_id()
--                 (SECURITY DEFINER, empty search_path, executable by `authenticated` only). It must
--                 exist before the policies below reference it.
--   [hand-edit 2] Privileges. RLS decides WHICH ROWS; privileges decide WHICH COLUMNS / OPERATIONS.
--     attendees        no browser writes; SELECT by owner/admin (policy) and only on non-secret
--                      columns: qr_uuid (the QR entry token) is readable by no browser role.
--     events           INSERT/UPDATE by owner/admin (policy). INSERT: the policy also requires
--                      ai_config and ai_config_version to be NULL (Drizzle sends DEFAULT for every
--                      column, so a column-level INSERT grant would break inserts). UPDATE: only
--                      title/status/start_date/end_date/updated_at; ai_config, ai_config_version and
--                      organization_id cannot be changed from the browser.
--     modules_registry INSERT/UPDATE by owner/admin (policy); UPDATE only on configuration/updated_at.
--     All three        no DELETE / TRUNCATE for browser roles; anon cannot write.
--     organizations, users, event_analytics_vectors
--                      no browser INSERT/UPDATE/DELETE. They had only Supabase's default privileges and
--                      were closed by RLS alone (no write policy); no app flow writes them from the
--                      browser (onboarding and analytics are server-side). SELECT stays (RLS-scoped).
--     All 12 tables    TRUNCATE, REFERENCES, TRIGGER and (PostgreSQL 17+ only) MAINTAIN revoked from
--                      anon/authenticated. They were present only because the default privileges grant
--                      ALL on new public tables (0003–0005 revoked INSERT/UPDATE/DELETE only). TRUNCATE
--                      and TRIGGER bypass RLS (a trigger runs on every row); REFERENCES lets a role
--                      probe keys via FKs; MAINTAIN allows REINDEX/LOCK. No app flow uses any of them.
--   [hand-edit 4] Default privileges for FUTURE objects (explicit-grant model): in schema-public and
--                 global pg_default_acl entries, anon/authenticated/PUBLIC lose EVERY privilege on new
--                 tables and sequences; a new table is closed to browser roles until the migration
--                 that creates it grants exactly what it needs (and the USAGE on its sequence, if any).
--                 In other schemas only TRUNCATE/REFERENCES/TRIGGER/MAINTAIN on tables are removed.
--                 service_role and existing tables' needed privileges are untouched. Existing public
--                 sequences (none today) lose all browser privileges.
--   [hand-edit 7] app.unsafe_default_acls_0006() lists default-privilege entries that would still
--                 expose new public tables/sequences: a creator role that can create in public whose
--                 entry the migrating role could not change, or a grant to a role anon/authenticated
--                 inherit. If it returns anything, the migration stops (nothing is applied).
--   [hand-edit 5] PUBLIC: nobody may write public tables or hold the four privileges through PUBLIC.
--   [hand-edit 6] Fail closed: after all changes, the EFFECTIVE privileges of anon/authenticated (direct,
--                 via PUBLIC, or via an inherited role) on existing tables and sequences are checked:
--                 DELETE/TRUNCATE/TRIGGER/MAINTAIN per table (has_table_privilege), INSERT/UPDATE/REFERENCES
--                 per column (has_column_privilege, which also sees column-level grants), SELECT on every
--                 attendees column (qr_uuid: nobody), sequences (has_sequence_privilege), and [hand-edit 7].
--                 Before all of these: anon/authenticated must not be able to switch to any other role
--                 (SET ROLE, ADMIN OPTION; CREATEROLE before PostgreSQL 16) — see the comment in the block;
--                 anything beyond the intended surface aborts the migration (nothing is applied).
--   [hand-edit 3] app.acl_before_0006: the ACLs of every public table and sequence, captured BEFORE
--                 any change, so the manual rollback restores exactly the privileges that existed (and
--                 nothing that did not); the full ACL is kept, PUBLIC entries included.
--                 app.default_acl_before_0006 does the same for the default privileges of anon,
--                 authenticated and PUBLIC (creator role, schema or global, object type, grantee,
--                 privilege, grant option). Both are server-only (no privileges for PUBLIC, anon,
--                 authenticated).
-- No data and no column changes: existing rows and QR tokens are untouched.
-- Server code (adminDb, role postgres) is not affected by RLS or these privileges.
-- Rollback: drizzle/rollback/0006_access_hardening.down.sql restores the 0005 surface. It is NOT in the
-- migration journal and never runs automatically; apply it by hand only if this migration must be undone.

-- [hand-edit 1]
create or replace function app.current_user_role()
returns public.user_role
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return (select u.role from public.users u where u.id = (select auth.uid()));
end;
$$;
--> statement-breakpoint
revoke all on function app.current_user_role() from public, anon;
--> statement-breakpoint
grant execute on function app.current_user_role() to authenticated;
--> statement-breakpoint

-- [hand-edit 3] pre-0006 privileges of every public table (read by the rollback SQL only)
create table app.acl_before_0006 (
  table_name text primary key,
  relkind "char" not null default 'r',
  table_acl text[],
  column_acls jsonb not null default '{}'::jsonb
);
--> statement-breakpoint
revoke all on app.acl_before_0006 from public, anon, authenticated;
--> statement-breakpoint
insert into app.acl_before_0006 (table_name, relkind, table_acl, column_acls)
select c.relname, c.relkind,
  (select array_agg(x::text order by x::text) from unnest(c.relacl) x),
  coalesce((select jsonb_object_agg(a.attname, (select array_agg(y::text order by y::text) from unnest(a.attacl) y))
            from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attacl is not null), '{}'::jsonb)
from pg_class c join pg_namespace n on n.oid = c.relnamespace
where n.nspname = 'public' and c.relkind in ('r', 'S');
--> statement-breakpoint
-- [hand-edit 3] pre-0006 default privileges of anon/authenticated, every object type and scope
create table app.default_acl_before_0006 (
  creator name not null,
  schema_name name,
  objtype "char" not null,
  grantee name not null,
  privilege_type text not null,
  is_grantable boolean not null
);
--> statement-breakpoint
revoke all on app.default_acl_before_0006 from public, anon, authenticated;
--> statement-breakpoint
insert into app.default_acl_before_0006 (creator, schema_name, objtype, grantee, privilege_type, is_grantable)
select pg_get_userbyid(d.defaclrole), n.nspname, d.defaclobjtype,
  case when e.grantee = 0 then 'PUBLIC' else pg_get_userbyid(e.grantee) end, e.privilege_type, e.is_grantable
from pg_default_acl d
left join pg_namespace n on n.oid = d.defaclnamespace
cross join lateral aclexplode(d.defaclacl) e
where e.grantee = 0 or pg_get_userbyid(e.grantee) in ('anon', 'authenticated');
--> statement-breakpoint

