-- [hand-edit 4] default privileges for FUTURE tables and sequences
--   schema public and global entries: anon, authenticated and PUBLIC get NOTHING on new tables or
--     sequences (explicit-grant model: the migration creating an object grants what it needs);
--   entries of other schemas: only TRUNCATE/REFERENCES/TRIGGER/MAINTAIN on tables are removed (other
--     subsystems' defaults are not ours to change).
do $$
declare
  d record;
begin
  for d in
    select a.defaclrole, n.nspname, a.defaclobjtype,
      case when e.grantee = 0 then 'public' else quote_ident(pg_get_userbyid(e.grantee)) end as grantee,
      string_agg(e.privilege_type, ', ' order by e.privilege_type) as privs
    from pg_default_acl a
    left join pg_namespace n on n.oid = a.defaclnamespace
    cross join lateral aclexplode(a.defaclacl) e
    where (e.grantee = 0 or pg_get_userbyid(e.grantee) in ('anon', 'authenticated'))
      and (
        (a.defaclobjtype in ('r', 'S') and (n.nspname is null or n.nspname = 'public'))
        or (a.defaclobjtype = 'r' and e.privilege_type in ('TRUNCATE', 'REFERENCES', 'TRIGGER', 'MAINTAIN'))
      )
    group by a.defaclrole, n.nspname, a.defaclobjtype, e.grantee
  loop
    if not pg_has_role(current_user, d.defaclrole, 'MEMBER') then
      -- cannot be changed from here; the fail-closed check at the end decides whether that is safe
      raise notice '0006: default privileges of role % (schema %) cannot be changed by %',
        pg_get_userbyid(d.defaclrole), coalesce(d.nspname, '<global>'), current_user;
      continue;
    end if;
    execute format('alter default privileges for role %I %s revoke %s on %s from %s',
      pg_get_userbyid(d.defaclrole), case when d.nspname is null then '' else format('in schema %I', d.nspname) end,
      d.privs, case d.defaclobjtype when 'r' then 'tables' else 'sequences' end, d.grantee);
  end loop;
end $$;
--> statement-breakpoint
-- existing sequences in public (none today): no browser access unless a migration grants it explicitly
do $$
declare
  q record;
begin
  for q in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'S' loop
    execute format('revoke all on sequence public.%I from anon, authenticated, public', q.relname);
  end loop;
end $$;
--> statement-breakpoint
-- [hand-edit 7] default-privilege entries that would still expose NEW public tables/sequences to browser
-- roles: entries of a creator role that can create in public, granting to anon/authenticated/PUBLIC
-- (left only if the migrating role cannot act for that creator) or to a role they inherit.
create function app.unsafe_default_acls_0006()
returns table (creator name, scope text, objtype text, grantee text, privileges text, reason text)
language sql
stable
set search_path = ''
as $$
  select pg_get_userbyid(d.defaclrole), coalesce(n.nspname, '<global>'), d.defaclobjtype::text,
    case when e.grantee = 0 then 'PUBLIC' else pg_get_userbyid(e.grantee) end,
    string_agg(e.privilege_type, ', ' order by e.privilege_type),
    case when e.grantee = 0 or pg_get_userbyid(e.grantee) in ('anon', 'authenticated')
      then case when pg_has_role(current_user, d.defaclrole, 'MEMBER')
                then 'grants browser roles access to new objects in public'
                else 'grants browser roles access to new objects in public; ' || current_user || ' cannot change this role''s default privileges' end
      else 'grants a role that anon/authenticated inherit' end
  from pg_catalog.pg_default_acl d
  join pg_catalog.pg_roles c on c.oid = d.defaclrole
  left join pg_catalog.pg_namespace n on n.oid = d.defaclnamespace
  cross join lateral pg_catalog.aclexplode(d.defaclacl) e
where d.defaclobjtype in ('r', 'S')
  and (n.nspname is null or n.nspname = 'public')
  and c.rolname <> 'supabase_admin'
  and (c.rolsuper or has_schema_privilege(c.oid, 'public', 'CREATE')
       or c.oid = (select ns.nspowner from pg_catalog.pg_namespace ns where ns.nspname = 'public'))
  and case when e.grantee = 0 then true  -- PUBLIC (guarded: pg_has_role cannot take OID 0)
             else pg_get_userbyid(e.grantee) in ('anon', 'authenticated')
               or pg_has_role('anon', e.grantee, 'USAGE') or pg_has_role('authenticated', e.grantee, 'USAGE') end
  group by d.defaclrole, n.nspname, d.defaclobjtype, e.grantee
$$;
--> statement-breakpoint
revoke all on function app.unsafe_default_acls_0006() from public, anon, authenticated;
--> statement-breakpoint
