revoke insert, update, delete, truncate, references, trigger on "ai_generations", "attendees", "event_analytics_vectors", "event_kpis", "events", "modules_registry", "organizations", "proposals", "survey_questions", "surveys", "tasks", "users" from public;
--> statement-breakpoint
