begin
  if current_setting('server_version_num')::int >= 170000 then
    execute 'revoke maintain on "ai_generations", "attendees", "event_analytics_vectors", "event_kpis", "events", "modules_registry", '
         || '"organizations", "proposals", "survey_questions", "surveys", "tasks", "users" from public';
  end if;
end $$;
--> statement-breakpoint
-- [hand-edit 6] fail closed on the EFFECTIVE privileges (direct, PUBLIC, role membership)
do $$
declare
  bad text;
  -- table-only privileges; INSERT/UPDATE/REFERENCES (which also exist per column) are checked per column below
  table_privs text[] := array['DELETE', 'TRUNCATE', 'TRIGGER'];
  switch_mode text;
begin
  -- ROLE SWITCHING. The checks below see a role's own privileges plus those inherited automatically
  -- (INHERIT). A browser role that can switch to another role (SET ROLE) gets that role's privileges
  -- without inheriting them, so no such path is allowed — not even to a platform role — and each one found
  -- is reported as "<browser role> -> <role> (direct|indirect[, admin option])".
  --   PostgreSQL 16+: a membership grant carries separate INHERIT / SET / ADMIN options. A path exists when
  --     pg_has_role(.., 'SET') is true (directly or through a chain of grants that all have SET).
  --     INHERIT-only grants are not a path: their privileges are inherited and checked below.
  --   PostgreSQL 15: there are no per-grant options and no 'SET' mode; every direct or indirect member may
  --     SET ROLE (NOINHERIT only stops automatic inheritance), so 'MEMBER' is the switch test there.
  --     CREATEROLE also lets a role grant itself any non-superuser role before 16, so it is a path too.
  --   All versions: ADMIN OPTION on a role lets the member grant that role to itself (with SET), so it is
  --     a path as well. A browser role's access to itself is not a switch and is excluded.
  -- 'SET' is passed to pg_has_role only inside this IF; pg_auth_members is used only through roleid/member,
  -- which exist on every supported version.
  if current_setting('server_version_num')::int >= 160000 then
    switch_mode := 'SET';
  else
    switch_mode := 'MEMBER';
  end if;
  select string_agg(format('%s -> %s (%s%s)', b.rolname, x.rolname,
      case when exists (select 1 from pg_auth_members m where m.member = b.oid and m.roleid = x.oid) then 'direct' else 'indirect' end,
      case when pg_has_role(b.oid, x.oid, 'MEMBER WITH ADMIN OPTION') then ', admin option' else '' end),
    '; ' order by b.rolname, x.rolname) into bad
  from pg_roles b
  cross join pg_roles x
  where b.rolname in ('anon', 'authenticated') and x.oid <> b.oid
    and (pg_has_role(b.oid, x.oid, switch_mode) or pg_has_role(b.oid, x.oid, 'MEMBER WITH ADMIN OPTION'));
  if current_setting('server_version_num')::int < 160000 then
    select concat_ws('; ', bad, string_agg(format('%s has CREATEROLE', b.rolname), '; ' order by b.rolname)) into bad
    from pg_roles b where b.rolname in ('anon', 'authenticated') and b.rolcreaterole;
    bad := nullif(bad, '');
  end if;
  if bad is not null then
    raise exception '0006: browser roles can switch to other roles (SET ROLE), which this access policy does not allow: %', bad;
  end if;
  -- MAINTAIN is an unknown privilege before PostgreSQL 17 (has_table_privilege would raise). It is added
  -- to the list only inside this IF, so on older servers it never reaches has_table_privilege at all —
  -- this does not depend on the order in which the planner evaluates the WHERE clause.
  if current_setting('server_version_num')::int >= 170000 then
    table_privs := table_privs || 'MAINTAIN'::text;
  end if;
  select string_agg(format('%s %s on %s', r.role, p.priv, c.relname), '; ' order by r.role, c.relname, p.priv) into bad
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  cross join (values ('anon'), ('authenticated')) r(role)
  cross join unnest(table_privs) p(priv)
  where n.nspname = 'public' and c.relkind = 'r'
    and has_table_privilege(r.role, c.oid, p.priv);
  if bad is not null then
    raise exception '0006: browser roles still hold privileges beyond the intended surface (directly, via PUBLIC or via role membership): %', bad;
  end if;
  -- INSERT/UPDATE/REFERENCES per column: has_column_privilege() is true for a column privilege AND for a
  -- table-level one, directly, via PUBLIC or via an inherited role. Intended (owner/admin by RLS):
  -- INSERT into events / modules_registry; UPDATE of the columns granted above and of tasks.status (0003).
  select string_agg(format('%s %s (%s) on %s', r.role, p.priv, a.attname, c.relname), '; ' order by r.role, c.relname, p.priv, a.attname) into bad
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
  cross join (values ('anon'), ('authenticated')) r(role)
  cross join (values ('INSERT'), ('UPDATE'), ('REFERENCES')) p(priv)
  where n.nspname = 'public' and c.relkind = 'r'
    and has_column_privilege(r.role, c.oid, a.attnum, p.priv)
    and not (r.role = 'authenticated' and (
          (p.priv = 'INSERT' and c.relname in ('events', 'modules_registry'))
       or (p.priv = 'UPDATE' and (c.relname::text, a.attname::text) in (
             ('events', 'title'), ('events', 'status'), ('events', 'start_date'), ('events', 'end_date'), ('events', 'updated_at'),
             ('modules_registry', 'configuration'), ('modules_registry', 'updated_at'),
             ('tasks', 'status'), ('tasks', 'updated_at')))));
  if bad is not null then
    raise exception '0006: browser roles hold column privileges beyond the intended surface (directly, via PUBLIC or via role membership): %', bad;
  end if;
  -- attendees: anon reads no column; authenticated (owner/admin by RLS) only the granted ones, never qr_uuid
  select string_agg(format('%s SELECT (%s) on attendees', r.role, a.attname), '; ' order by r.role, a.attname) into bad
  from pg_attribute a
  cross join (values ('anon'), ('authenticated')) r(role)
  where a.attrelid = 'public.attendees'::regclass and a.attnum > 0 and not a.attisdropped
    and has_column_privilege(r.role, a.attrelid, a.attnum, 'SELECT')
    and not (r.role = 'authenticated' and a.attname::text in
             ('id', 'organization_id', 'event_id', 'ticket_type', 'is_checked_in', 'checked_in_at', 'created_at', 'updated_at'));
  if bad is not null then
    raise exception '0006: browser roles can read attendee columns beyond the intended surface (directly, via PUBLIC or via role membership): %', bad;
  end if;
  select string_agg(format('%s %s on sequence %s', r.role, p.priv, c.relname), '; ') into bad
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  cross join (values ('anon'), ('authenticated')) r(role)
  cross join (values ('USAGE'), ('SELECT'), ('UPDATE')) p(priv)
  where n.nspname = 'public' and c.relkind = 'S' and has_sequence_privilege(r.role, c.oid, p.priv);
  if bad is not null then
    raise exception '0006: browser roles still hold sequence privileges: %', bad;
  end if;
  -- future objects: stop instead of assuming the live environment's default privileges are harmless
  select string_agg(format('%s/%s/%s -> %s (%s): %s', u.creator, u.scope, u.objtype, u.grantee, u.privileges, u.reason), '; ') into bad
  from app.unsafe_default_acls_0006() u;
  if bad is not null then
    raise exception '0006: default privileges would expose new public tables/sequences: %. Fix them (as a role that may act for the creator) and re-run.', bad;
  end if;
end $$;
